using System.Text.Json.Nodes;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace Hawa.Grasshopper;

public sealed class AirfoilComponent:HawaComponent {
    public AirfoilComponent():base("Hawa Airfoil","Airfoil","Generate NACA four-digit coordinates or read a local Selig/Lednicer file. No downloads.","09 Airfoils"){}
    public override Guid ComponentGuid=>new("a7bb3b0a-ae4f-42ae-9301-a3c55f077125");
    protected override void RegisterInputParams(GH_InputParamManager p){p.AddTextParameter("NACA or file","S","Four digits or a local coordinate file path",GH_ParamAccess.item,"2412");p.AddNumberParameter("Chord","C","Model length",GH_ParamAccess.item,1);p.AddPlaneParameter("Plane","P","Profile plane",GH_ParamAccess.item,Plane.WorldXY);}
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddCurveParameter("Profile","C","Airfoil polyline",GH_ParamAccess.item);p.AddGenericParameter("Airfoil","A","Coordinates and provenance",GH_ParamAccess.item);p.AddTextParameter("Source","S","Data source",GH_ParamAccess.item);}
    protected override void SolveHawa(IGH_DataAccess da){string source="2412";double chord=1;Plane plane=Plane.WorldXY;da.GetData(0,ref source);da.GetData(1,ref chord);da.GetData(2,ref plane);if(!double.IsFinite(chord)||chord<=0)throw new ArgumentException("Chord must be positive");string code=source.ToUpperInvariant().Replace("NACA","").Trim();bool generated=code.Length==4&&code.All(char.IsDigit);var req=new JsonObject{["op"]="airfoil",["action"]=generated?"naca":"import",[generated?"code":"path"]=generated?code:LocalPath(source)};var data=EmbeddedRuntime.Call(req);data["kind"]="Airfoil";da.SetData(0,new PolylineCurve(data["coordinates"]!.AsArray().Select(p=>plane.PointAt(chord*p![0]!.GetValue<double>(),chord*p[1]!.GetValue<double>()))));da.SetData(1,new HawaGoo(data));da.SetData(2,data["source"]!.GetValue<string>());}
}

public sealed class PolarComponent:HawaComponent {
    public PolarComponent():base("Hawa Polar Data","Polar","Read a local CSV or XFOIL polar. Preserve operating conditions. No downloads or extrapolation.","09 Airfoils"){}
    public override Guid ComponentGuid=>new("a7bb3b0a-ae4f-42ae-9301-a3c55f077126");
    protected override void RegisterInputParams(GH_InputParamManager p){p.AddTextParameter("File","P","Local polar with alpha cl cd and optional cm",GH_ParamAccess.item);p.AddNumberParameter("Reynolds","Re","Data Reynolds number",GH_ParamAccess.item,100000);p.AddNumberParameter("Mach","Ma","Data Mach number",GH_ParamAccess.item,0);p.AddNumberParameter("Angle","A","Requested angle in degrees within data range",GH_ParamAccess.item,0);}
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddGenericParameter("Polar","P","Data with provenance",GH_ParamAccess.item);p.AddNumberParameter("Cl","Cl","Section lift coefficient",GH_ParamAccess.item);p.AddNumberParameter("Cd","Cd","Section drag coefficient",GH_ParamAccess.item);p.AddCurveParameter("Lift curve","L","X=alpha, Y=Cl",GH_ParamAccess.item);p.AddCurveParameter("Drag polar","D","X=Cd, Y=Cl",GH_ParamAccess.item);p.AddTextParameter("Conditions","C","Source and conditions",GH_ParamAccess.item);p.AddNumberParameter("Cm","Cm","Pitching moment coefficient when supplied",GH_ParamAccess.item);p.AddNumberParameter("Lift / drag","L/D","Cl/Cd when Cd is positive",GH_ParamAccess.item);}
    protected override void SolveHawa(IGH_DataAccess da){string path="";double re=100000,mach=0,alpha=0;da.GetData(0,ref path);da.GetData(1,ref re);da.GetData(2,ref mach);da.GetData(3,ref alpha);var data=EmbeddedRuntime.Call(new JsonObject{["op"]="airfoil",["action"]="polar",["path"]=LocalPath(path),["reynolds"]=re,["mach"]=mach});var value=EmbeddedRuntime.Call(new JsonObject{["op"]="airfoil",["action"]="operating_point",["polar"]=data.DeepClone(),["alpha"]=alpha});if(value["cm"]!=null)da.SetData(6,value["cm"]!.GetValue<double>());if(value["lift_drag"]!=null)da.SetData(7,value["lift_drag"]!.GetValue<double>());data["kind"]="Polar";da.SetData(0,new HawaGoo(data));da.SetData(1,value["cl"]!.GetValue<double>());da.SetData(2,value["cd"]!.GetValue<double>());var rows=data["rows"]!.AsArray();da.SetData(3,new PolylineCurve(rows.Select(r=>new Point3d(r![0]!.GetValue<double>(),r[1]!.GetValue<double>(),0))));da.SetData(4,new PolylineCurve(rows.Select(r=>new Point3d(r![2]!.GetValue<double>(),r[1]!.GetValue<double>(),0))));da.SetData(5,$"{data["source"]}\nRe={re:g6}; Mach={mach:g4}\n{data["conditions"]}");}
}

public sealed class WingComponent:HawaComponent {
    public WingComponent():base("Hawa Wing","Wing","Parametric unswept wing with linear taper and washout. Airfoil coordinates remain editable.","10 Aircraft"){}
    public override Guid ComponentGuid=>new("a7bb3b0a-ae4f-42ae-9301-a3c55f077127");
    protected override void RegisterInputParams(GH_InputParamManager p){p.AddGenericParameter("Airfoil","A","Hawa Airfoil data",GH_ParamAccess.item);p.AddNumberParameter("Span","B","Full span",GH_ParamAccess.item,2);p.AddNumberParameter("Root chord","Cr","Root chord",GH_ParamAccess.item,.3);p.AddNumberParameter("Tip chord","Ct","Tip chord",GH_ParamAccess.item,.15);p.AddNumberParameter("Twist","T","Tip angle relative to root in degrees",GH_ParamAccess.item,-2);}
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddMeshParameter("Wing","W","Closed wing mesh",GH_ParamAccess.item);p.AddCurveParameter("Sections","S","Spanwise airfoil sections",GH_ParamAccess.list);}
    protected override void SolveHawa(IGH_DataAccess da){var foil=ReadObject(da,0);double span=2,root=.3,tip=.15,twist=-2;da.GetData(1,ref span);da.GetData(2,ref root);da.GetData(3,ref tip);da.GetData(4,ref twist);if(new[]{span,root,tip,twist}.Any(x=>!double.IsFinite(x))||Math.Min(span,Math.Min(root,tip))<=0)throw new ArgumentException("Positive finite dimensions required");var xy=foil["coordinates"]!.AsArray().Select(p=>new Point2d(p![0]!.GetValue<double>(),p[1]!.GetValue<double>())).ToList();if(xy[0].DistanceTo(xy[^1])<1e-9)xy.RemoveAt(xy.Count-1);var mesh=new Mesh();var sections=new List<Curve>();const int n=21;int ring=xy.Count;for(int i=0;i<n;i++){double eta=2d*i/(n-1)-1,c=root+(tip-root)*Math.Abs(eta),a=twist*Math.Abs(eta)*Math.PI/180;var points=new List<Point3d>();foreach(var p in xy){double x=(p.X-.25)*c,z=p.Y*c;var q=new Point3d(x*Math.Cos(a)+z*Math.Sin(a),eta*span/2,-x*Math.Sin(a)+z*Math.Cos(a));points.Add(q);mesh.Vertices.Add(q);}points.Add(points[0]);sections.Add(new PolylineCurve(points));}for(int i=0;i<n-1;i++)for(int j=0;j<ring;j++){int a=i*ring+j,b=i*ring+(j+1)%ring;mesh.Faces.AddFace(a,b,b+ring,a+ring);}foreach(int side in new[]{0,n-1}){var indices=Enumerable.Range(side*ring,ring).ToArray();var center=new Point3d(indices.Average(i=>mesh.Vertices[i].X),indices.Average(i=>mesh.Vertices[i].Y),indices.Average(i=>mesh.Vertices[i].Z));int k=mesh.Vertices.Add(center);for(int j=0;j<ring;j++)mesh.Faces.AddFace(k,indices[j],indices[(j+1)%ring]);}mesh.UnifyNormals();if(mesh.SolidOrientation()<0)mesh.Flip(true,true,true);mesh.Normals.ComputeNormals();da.SetData(0,mesh);da.SetDataList(1,sections);}
}

public sealed class WingAnalysisComponent:HawaComponent {
    public WingAnalysisComponent():base("Hawa Wing Analysis","LLT","Linear lifting-line analysis of an unswept wing. Attached flow. Induced drag only.","10 Aircraft"){}
    public override Guid ComponentGuid=>new("a7bb3b0a-ae4f-42ae-9301-a3c55f077128");
    protected override void RegisterInputParams(GH_InputParamManager p){p.AddNumberParameter("Span","B","Full span",GH_ParamAccess.item,2);p.AddNumberParameter("Root chord","Cr","Chord",GH_ParamAccess.item,.3);p.AddNumberParameter("Tip chord","Ct","Chord",GH_ParamAccess.item,.15);p.AddNumberParameter("Angle","A","Degrees",GH_ParamAccess.item,4);p.AddNumberParameter("Twist","T","Tip twist degrees",GH_ParamAccess.item,-2);p.AddNumberParameter("Zero lift angle","A0","Section zero-lift angle from polar data",GH_ParamAccess.item,0);p.AddGenericParameter("Polar","P","Optional matching attached-flow local polar for profile drag",GH_ParamAccess.item);p[6].Optional=true;}
    protected override void RegisterOutputParams(GH_OutputParamManager p){p.AddNumberParameter("CL","CL","Wing lift coefficient",GH_ParamAccess.item);p.AddNumberParameter("CDi","CDi","Induced drag coefficient",GH_ParamAccess.item);p.AddCurveParameter("Span loads","L","X=span position, Y=section Cl",GH_ParamAccess.item);p.AddTextParameter("Scope","S","Analysis assumptions",GH_ParamAccess.item);p.AddNumberParameter("Profile drag","CDp","Requires local polar",GH_ParamAccess.item);p.AddNumberParameter("Total drag","CD","Induced plus supplied profile drag",GH_ParamAccess.item);}
    protected override void SolveHawa(IGH_DataAccess da){var names=new[]{"span","root_chord","tip_chord","alpha","twist","alpha_zero"};var req=new JsonObject{["op"]="airfoil",["action"]="wing"};for(int i=0;i<6;i++){double v=0;da.GetData(i,ref v);req[names[i]]=v;}if(Params.Input[6].VolatileDataCount>0)req["polar"]=ReadObject(da,6);var r=EmbeddedRuntime.Call(req);if(r["CD_profile"]!=null){da.SetData(4,r["CD_profile"]!.GetValue<double>());da.SetData(5,r["CD_total"]!.GetValue<double>());}da.SetData(0,r["CL"]!.GetValue<double>());da.SetData(1,r["CDi"]!.GetValue<double>());da.SetData(2,new PolylineCurve(r["span_positions"]!.AsArray().Select((x,i)=>new Point3d(x!.GetValue<double>(),r["section_cl"]![i]!.GetValue<double>(),0))));da.SetData(3,r["limits"]!.GetValue<string>());}
}
